import { writable } from 'svelte/store';

const initialHint = {
	show: false,
	candidates: [],
	hintCell: null,
	reasoning: '',
	level: '',
	technique: '',
};

function createHintDisplay() {
	const { subscribe, set } = writable({ ...initialHint });

	return {
		subscribe,

		showCandidates(pos, candidates) {
			set({
				show: true,
				candidates,
				hintCell: pos ? { x: pos.x, y: pos.y } : null,
				reasoning: candidates.length
					? `Cell (${pos.y + 1},${pos.x + 1}) can contain: ${candidates.join(', ')}.`
					: `Cell (${pos.y + 1},${pos.x + 1}) has no available candidates.`,
				level: 'candidates',
				technique: 'Candidates',
			});
		},

		showHint(hint) {
			if (!hint) {
				set({
					...initialHint,
					show: true,
					reasoning: 'No deterministic hint is available. Exploration mode can be used from here.',
					level: 'none',
					technique: 'No Hint',
				});
				return;
			}

			set({
				show: true,
				candidates: hint.value ? [hint.value] : [],
				hintCell: { x: hint.col, y: hint.row },
				reasoning: hint.reason,
				level: hint.level,
				technique: hint.technique === 'naked-single'
					? 'Naked Single'
					: hint.technique === 'hidden-single'
						? 'Hidden Single'
						: 'Solver Hint',
			});
		},

		clear() {
			set({ ...initialHint });
		},
	};
}

export const hintDisplay = createHintDisplay();
